# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_extension() {
    local listing
    listing="$(hunk extension list 2>/dev/null)" || return 0
    [[ -n "$listing" ]] || return 0
    printf '%s\n' "$listing" | sed -n 's/^\([^[:space:]]\{1,\}\)  .*/\1/p'
}

_choice_gh_commit() {
    git log --all --format='%h%x09%s' -n 100 2>/dev/null
}

_choice_gh_compare() {
    local refs
    refs="$(git for-each-ref --count=500 --format='%(refname:short)' refs/heads refs/remotes refs/tags 2>/dev/null)" || return 0
    [[ -n "$refs" ]] || return 0
    _argc_util_mode_parts '...'
    if [[ "$ARGC_CWORD" == *...* ]]; then
        printf '%s\n' "$refs"
    else
        printf '%s\n' "$refs" | _argc_util_transform suffix=... nospace
    fi
}

_choice_patch_options() {
    local offset="${argc__dash:-1}"
    argc__positionals=( "${argc__positionals[@]:$offset}" )
    _argc_util_comp_subcommand 0 hunk patch
}

_choice_ref() {
    git rev-parse --is-inside-work-tree >/dev/null 2>&1 || return 0
    if [[ "$ARGC_CWORD" == *...* ]]; then
        _argc_util_mode_parts ...
    else
        _argc_util_mode_parts ..
    fi
    _helper_git_rev
    if [[ "${argc__cmd_fn:-}" == diff ]]; then
        _argc_util_comp_path
    fi
}

_choice_session() {
    local sessions
    sessions="$(hunk session list --json 2>/dev/null)" || return 0
    [[ -n "$sessions" ]] || return 0
    jq -b -r '.sessions[]? | (.sessionId // .id // .session_id // empty) | select(type == "string" and length > 0)' <<<"$sessions" 2>/dev/null || return 0
}

_choice_skill() {
    printf '%s\n' hunk-review review hunk-extensions extensions
}

_choice_stash() {
    git rev-parse --is-inside-work-tree >/dev/null 2>&1 || return 0
    git stash list --format='%gd' 2>/dev/null || return 0
}

_choice_tone() {
    printf '%s\n' match current info warning error dim
}

_choice_wheel_scroll_lines() {
    printf 'auto\n'
    local i
    for ((i = 1; i <= 10; i++)); do
        printf '%d\n' "$i"
    done
}

_helper_git_rev() {
    printf 'HEAD\n'
    git for-each-ref --count=500 --format='%(refname:short)' refs/heads refs/remotes refs/tags 2>/dev/null || return 0
    git log --all --format='%h' -n 50 2>/dev/null || return 0
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
